/* Original C definitions for the bounded ordinary-character literal family. */
#define CHARACTER_DIGIT(unused) '0'
#define CHARACTER_UPPER(unused) 'A'
#define CHARACTER_LOWER(unused) 'z'
#define CHARACTER_SPACE(unused) ' '
#define CHARACTER_TILDE(unused) '~'
#define CHARACTER_QUOTE(unused) '\''
#define CHARACTER_DOUBLE_QUOTE(unused) '\"'
#define CHARACTER_QUESTION(unused) '\?'
#define CHARACTER_BACKSLASH(unused) '\\'
#define CHARACTER_ALERT(unused) '\a'
#define CHARACTER_BACKSPACE(unused) '\b'
#define CHARACTER_FORMFEED(unused) '\f'
#define CHARACTER_NEWLINE(unused) '\n'
#define CHARACTER_RETURN(unused) '\r'
#define CHARACTER_TAB(unused) '\t'
#define CHARACTER_VERTICAL_TAB(unused) '\v'
#define CHARACTER_OCTAL_ZERO(unused) '\0'
#define CHARACTER_OCTAL_ONE(unused) '\1'
#define CHARACTER_OCTAL_TWO_DIGITS(unused) '\12'
#define CHARACTER_OCTAL_MAX(unused) '\177'
#define CHARACTER_HEX_ZERO(unused) '\x00'
#define CHARACTER_HEX_MAX(unused) '\x7f'
#define CHARACTER_HEX_LEADING_ZEROES(unused) '\x0000000000000000000000007F'
#define CHARACTER_OFFSET(x) (((x) - '0') & 0x3F)
#define CHARACTER_REPEAT(x) (((x) + '0') + ((x) + '0'))
#define CHARACTER_COMPARE(x) ((x) < '0')
#define CHARACTER_WIDE(unused) L'a'
#define CHARACTER_UTF16(unused) u'a'
#define CHARACTER_UTF32(unused) U'a'
#define CHARACTER_MULTIPLE(unused) 'ab'
#define CHARACTER_NONASCII(unused) 'é'
#define CHARACTER_UNIVERSAL(unused) '\u00E9'
#define CHARACTER_UNKNOWN_ESCAPE(unused) '\e'
#define CHARACTER_OCTAL_HIGH(unused) '\200'
#define CHARACTER_HEX_HIGH(unused) '\x80'
#define CHARACTER_NOT_BASIC(unused) '@'
